        // Expect Pushed event for token2
        vm.expectEmit(true, true, true, true);
        emit IAqua.Pushed(maker, app, strategyHash, address(token2), 200e18);

        vm.prank(maker);
        aqua.ship(
            app,
            strategy,
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );
    }

    // ========== DOCK EVENTS ==========

    function testDockEmitsDockedEvent() public {
        bytes memory strategy = "strategy_docked";
        bytes32 strategyHash = keccak256(strategy);

        // First ship the strategy
        vm.prank(maker);
        aqua.ship(
            app,
            strategy,
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Expect Docked event
        vm.expectEmit(true, true, true, true);
        emit IAqua.Docked(maker, app, strategyHash);

        vm.prank(maker);
        aqua.dock(
            app,
            strategyHash,
            dynamic([address(token1)])
        );
    }

    // ========== PUSH EVENTS ==========

    function testPushEmitsPushedEvent() public {
        bytes memory strategy = "strategy_push";
        bytes32 strategyHash = keccak256(strategy);

        // First ship the strategy
        vm.prank(maker);
        aqua.ship(
            app,
            strategy,
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Expect Pushed event
        vm.expectEmit(true, true, true, true);
        emit IAqua.Pushed(maker, app, strategyHash, address(token1), 50e18);

        vm.prank(pusher);
        aqua.push(maker, app, strategyHash, address(token1), 50e18);
    }

    // ========== PULL EVENTS ==========

    function testPullEmitsPulledEvent() public {
        bytes memory strategy = "strategy_pull";
        bytes32 strategyHash = keccak256(strategy);

        // First ship the strategy
        vm.prank(maker);
        aqua.ship(
            app,
            strategy,
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Expect Pulled event
        vm.expectEmit(true, true, true, true);
        emit IAqua.Pulled(maker, app, strategyHash, address(token1), 30e18);

        vm.prank(app);
        aqua.pull(maker, strategyHash, address(token1), 30e18, app);
    }
}

project/test/AquaLifecycle.t.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-Aqua-Source-1.1
pragma solidity ^0.8.13;

/// @custom:license-url https://github.com/1inch/aqua/blob/main/LICENSES/Aqua-Source-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { dynamic } from "./utils/Dynamic.sol";
import { AquaTestBase } from "./base/AquaTestBase.sol";
import { IAqua } from "../src/interfaces/IAqua.sol";

contract AquaLifecycleTest is AquaTestBase {
    // ========== COMPLEX LIFECYCLE TESTS ==========

    function testFullLifecycle() public {
        bytes32 strategyHash = keccak256("lifecycle");
        uint256 newBalance;

        // 1. Ship with 2 tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "lifecycle",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // 2. Push to token1
        vm.prank(pusher);
        aqua.push(maker, app, strategyHash, address(token1), 50e18);
        (newBalance,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(newBalance, 150e18);

        // 3. Pull from app
        vm.prank(app);
        aqua.pull(maker, strategyHash, address(token1), 30e18, app);
        (newBalance,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(newBalance, 120e18);

        // 4. Dock all tokens
        vm.prank(maker);
        aqua.dock(
            app,
            strategyHash,
            dynamic([address(token1), address(token2)])
        );

        // 5. Verify can't push after dock
        vm.prank(pusher);
        vm.expectRevert(abi.encodeWithSelector(IAqua.PushToNonActiveStrategyPrevented.selector, maker, app, strategyHash, address(token1)));
        aqua.push(maker, app, strategyHash, address(token1), 10e18);

        // 6. Verify balances are zero after dock
        (newBalance,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(newBalance, 0);
        (newBalance,) = aqua.rawBalances(maker, app, strategyHash, address(token2));
        assertEq(newBalance, 0);
    }

    function testMultipleStrategiesSameTokens() public {
        uint256 newBalance;

        // Ship strategy 1
        vm.prank(maker);
        aqua.ship(
            app,
            "multi1",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Ship strategy 2 with same tokens but different salt
        vm.prank(maker);
        aqua.ship(
            app,
            "multi2",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(300e18), uint256(400e18)])
        );

        // Verify both strategies work independently
        bytes32 hash1 = keccak256("multi1");
        bytes32 hash2 = keccak256("multi2");

        (newBalance,) = aqua.rawBalances(maker, app, hash1, address(token1));
        assertEq(newBalance, 100e18);
        (newBalance,) = aqua.rawBalances(maker, app, hash2, address(token1));
        assertEq(newBalance, 300e18);

        // Push to strategy 1 doesn't affect strategy 2
        vm.prank(pusher);
        aqua.push(maker, app, hash1, address(token1), 50e18);

        (newBalance,) = aqua.rawBalances(maker, app, hash1, address(token1));
        assertEq(newBalance, 150e18);
        (newBalance,) = aqua.rawBalances(maker, app, hash2, address(token1));
        assertEq(newBalance, 300e18);

        // Can dock strategies independently
        vm.prank(maker);
        aqua.dock(app, hash1, dynamic([address(token1), address(token2)]));

        // Strategy 1 is docked, strategy 2 still active
        (newBalance,) = aqua.rawBalances(maker, app, hash1, address(token1));
        assertEq(newBalance, 0);
        (newBalance,) = aqua.rawBalances(maker, app, hash2, address(token1));
        assertEq(newBalance, 300e18);
    }
}

project/test/AquaPushPull.t.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-Aqua-Source-1.1
pragma solidity ^0.8.13;

/// @custom:license-url https://github.com/1inch/aqua/blob/main/LICENSES/Aqua-Source-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { dynamic } from "./utils/Dynamic.sol";
import { AquaTestBase } from "./base/AquaTestBase.sol";
import { IAqua } from "../src/interfaces/IAqua.sol";
import { stdError } from "forge-std/StdError.sol";

contract AquaPushPullTest is AquaTestBase {
    // ========== PUSH TESTS ==========

    function testPushRequiresActiveStrategy() public {
        // Try to push without ship
        vm.prank(pusher);
        vm.expectRevert(abi.encodeWithSelector(IAqua.PushToNonActiveStrategyPrevented.selector, maker, app, keccak256("nonexistent"), address(token1)));
        aqua.push(maker, app, keccak256("nonexistent"), address(token1), 100e18);
    }

    function testPushFailsAfterDock() public {
        // Ship and then dock
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy5",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        vm.prank(maker);
        aqua.dock(
            app,
            keccak256("strategy5"),
            dynamic([address(token1)])
        );

        // Try to push after dock
        vm.prank(pusher);
        vm.expectRevert(abi.encodeWithSelector(IAqua.PushToNonActiveStrategyPrevented.selector, maker, app, keccak256("strategy5"), address(token1)));
        aqua.push(maker, app, keccak256("strategy5"), address(token1), 50e18);
    }

    function testPushOnlyForShippedTokens() public {
        // Ship with token1 only
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy6",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Try to push token2 (not shipped)
        vm.prank(pusher);
        vm.expectRevert(abi.encodeWithSelector(IAqua.PushToNonActiveStrategyPrevented.selector, maker, app, keccak256("strategy6"), address(token2)));
        aqua.push(maker, app, keccak256("strategy6"), address(token2), 50e18);
    }

    // ========== PULL TESTS ==========

    function testPullRevertsOnInsufficientBalance() public {
        // Ship a strategy with 100 tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "pull_underflow",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Try to pull more than available - should revert (arithmetic underflow)
        vm.prank(app);
        vm.expectRevert(stdError.arithmeticError);
        aqua.pull(maker, keccak256("pull_underflow"), address(token1), 150e18, app);
    }

    function testPullFromNonExistentStrategy() public {
        // Pull from non-existent strategy - balance is 0, so any pull amount will underflow
        vm.prank(app);
        vm.expectRevert(stdError.arithmeticError);
        aqua.pull(maker, keccak256("nonexistent_pull"), address(token1), 1e18, app);
    }

    function testPullAfterDockRevertsOnUnderflow() public {
        // Ship and dock a strategy
        vm.prank(maker);
        aqua.ship(
            app,
            "pull_docked",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        vm.prank(maker);
        aqua.dock(
            app,
            keccak256("pull_docked"),
            dynamic([address(token1)])
        );

        // Try to pull after dock - balance is 0, so will underflow
        vm.prank(app);
        vm.expectRevert(stdError.arithmeticError);
        aqua.pull(maker, keccak256("pull_docked"), address(token1), 50e18, app);
    }

    // ========== OVERFLOW TESTS ==========

    function testPushAccumulatesBalance() public {
        // Test that push correctly accumulates balance without overflow
        // Ship with max available tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_overflow",
            dynamic([address(token1)]),
            dynamic([uint256(9000e18)]) // maker has 10000e18
        );

        bytes32 strategyHash = keccak256("strategy_overflow");

        // Pusher has 10000e18 tokens, push would make balance 19000e18 - this works
        vm.prank(pusher);
        aqua.push(maker, app, strategyHash, address(token1), 1000e18);

        (uint256 balance,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(balance, 10000e18);
    }

    function testPushRevertsOnUint248Overflow() public {
        // This test verifies that pushing an amount that would overflow uint248 reverts
        // The contract uses SafeCast which will revert on overflow

        // Ship a strategy
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_uint248_overflow",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        bytes32 strategyHash = keccak256("strategy_uint248_overflow");

        // Try to push an amount larger than uint248 max
        // This will fail at SafeCast.toUint248() in push function
        uint256 tooLargeAmount = uint256(type(uint248).max) + 1;

        vm.prank(pusher);
        vm.expectRevert(); // SafeCast overflow
        aqua.push(maker, app, strategyHash, address(token1), tooLargeAmount);
    }

    function testPushRevertsOnBalanceOverflow() public {
        // This test verifies that pushing causes overflow when prevBalance + amount > uint248 max
        // Ship with a large initial balance close to uint248 max
        uint256 largeInitialBalance = uint256(type(uint248).max) - 100e18;

        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_balance_overflow",
            dynamic([address(token1)]),
            dynamic([largeInitialBalance])
        );

        bytes32 strategyHash = keccak256("strategy_balance_overflow");

        // Verify initial balance
        (uint256 balance,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(balance, largeInitialBalance);

        // Try to push an amount that would cause prevBalance + amount to overflow uint248
        // 200e18 > 100e18 remaining space, so this should overflow
        vm.prank(pusher);
        vm.expectRevert(stdError.arithmeticError);
        aqua.push(maker, app, strategyHash, address(token1), 200e18);
    }

    function testShipRevertsOnUint248AmountOverflow() public {
        // Test that shipping with amount > uint248 max reverts
        uint256 tooLargeAmount = uint256(type(uint248).max) + 1;

        vm.prank(maker);
        vm.expectRevert(); // SafeCast overflow
        aqua.ship(
            app,
            "strategy_ship_overflow",
            dynamic([address(token1)]),
            dynamic([tooLargeAmount])
        );
    }
}

project/test/AquaShipDock.t.sol.content:
// SPDX-License-Identifier: LicenseRef-Degensoft-Aqua-Source-1.1
pragma solidity ^0.8.13;

/// @custom:license-url https://github.com/1inch/aqua/blob/main/LICENSES/Aqua-Source-1.1.txt
/// @custom:copyright © 2025 Degensoft Ltd

import { dynamic } from "./utils/Dynamic.sol";
import { AquaTestBase } from "./base/AquaTestBase.sol";
import { IAqua } from "../src/interfaces/IAqua.sol";

contract AquaShipDockTest is AquaTestBase {
    // ========== SHIP TESTS ==========

    function testShipRevertsWhenTokenCountEquals255() public {
        // Create arrays with 255 tokens (which equals _DOCKED constant)
        address[] memory tokens = new address[](255);
        uint256[] memory amounts = new uint256[](255);

        for (uint256 i = 0; i < 255; i++) {
            tokens[i] = address(uint160(i + 1000)); // unique addresses
            amounts[i] = 1e18;
        }

        // Should revert with MaxNumberOfTokensExceeded(255, 254)
        // The actual maximum allowed is 254 (_DOCKED - 1)
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.MaxNumberOfTokensExceeded.selector, 255, 254));
        aqua.ship(app, "strategy_255", tokens, amounts);
    }

    function testShipRevertsWhenTokenCountExceeds255() public {
        // Create arrays with 256 tokens (exceeds uint8 max, SafeCast will revert)
        address[] memory tokens = new address[](256);
        uint256[] memory amounts = new uint256[](256);

        for (uint256 i = 0; i < 256; i++) {
            tokens[i] = address(uint160(i + 1000)); // unique addresses
            amounts[i] = 1e18;
        }

        // Should revert with SafeCast overflow (before reaching MaxNumberOfTokensExceeded check)
        vm.prank(maker);
        vm.expectRevert(); // SafeCast.toUint8() overflow
        aqua.ship(app, "strategy_256", tokens, amounts);
    }

    function testShipCannotBeCalledTwiceForSameStrategy() public {
        // First ship
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy1",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Try to ship again with same strategy
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.StrategiesMustBeImmutable.selector, app, keccak256("strategy1")));
        aqua.ship(
            app,
            "strategy1",
            dynamic([address(token1)]),
            dynamic([uint256(50e18)])
        );
    }

    function testShipSameStrategyHashDifferentTokens() public {
        bytes32 strategyHash = keccak256("shared_strategy");

        // First ship with token1 and token2
        vm.prank(maker);
        aqua.ship(
            app,
            "shared_strategy",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Verify initial state
        (uint256 balance1, uint8 tokensCount1) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (uint256 balance2, uint8 tokensCount2) = aqua.rawBalances(maker, app, strategyHash, address(token2));
        assertEq(balance1, 100e18);
        assertEq(balance2, 200e18);
        assertEq(tokensCount1, 2);
        assertEq(tokensCount2, 2);

        // Try to ship again with completely different tokens (no overlap)
        // Should revert because once any token is set for a strategyHash,
        // attempting to add new tokens would create inconsistent tokensCount state
        vm.prank(maker);
        aqua.ship(
            app,
            "shared_strategy",
            dynamic([address(token3)]),
            dynamic([uint256(300e18)])
        );

        // Verify token3 was added but with inconsistent tokensCount
        (uint256 balance3, uint8 tokensCount3) = aqua.rawBalances(maker, app, strategyHash, address(token3));
        assertEq(balance3, 300e18);
        assertEq(tokensCount3, 1); // This is inconsistent with token1/token2 having tokensCount=2

        // This creates a problematic state where:
        // - token1 and token2 have tokensCount=2
        // - token3 has tokensCount=1
        // Docking this strategy would be impossible because no tokens array would satisfy all requirements
    }

    function testShipSameStrategyHashPartiallyOverlappingTokensReverts() public {
        // First ship with token1 and token2
        vm.prank(maker);
        aqua.ship(
            app,
            "overlap_strategy",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Try to ship again with partially overlapping tokens (token1 exists, token3 is new)
        // Should revert when it encounters token1 which already has tokensCount > 0
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.StrategiesMustBeImmutable.selector, app, keccak256("overlap_strategy")));
        aqua.ship(
            app,
            "overlap_strategy",
            dynamic([address(token1), address(token3)]),
            dynamic([uint256(50e18), uint256(150e18)])
        );
    }

    function testShipCannotHaveDuplicateTokens() public {
        // The contract prevents duplicate tokens in the same ship call
        // because it checks tokensCount == 0 for each token
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.StrategiesMustBeImmutable.selector, app, keccak256("strategy_dup")));
        aqua.ship(
            app,
            "strategy_dup",
            dynamic([address(token1), address(token1)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );
    }

    function testShipWithLargeAmountsPreservesTokenCount() public {
        // Ship with large amounts to verify tokensCount is not overwritten by balance
        // The Balance struct packs amount (uint248) and tokensCount (uint8) in one slot
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_large",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(1000e18), uint256(2000e18)])
        );

        bytes32 strategyHash = keccak256("strategy_large");

        // Verify tokensCount is preserved correctly
        (uint256 balance1, uint8 tokensCount1) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (uint256 balance2, uint8 tokensCount2) = aqua.rawBalances(maker, app, strategyHash, address(token2));

        assertEq(balance1, 1000e18);
        assertEq(balance2, 2000e18);
        assertEq(tokensCount1, 2, "tokensCount should be 2, not overwritten by amount");
        assertEq(tokensCount2, 2, "tokensCount should be 2, not overwritten by amount");

        // Push more tokens and verify tokensCount still preserved
        vm.prank(pusher);
        aqua.push(maker, app, strategyHash, address(token1), 500e18);

        (balance1, tokensCount1) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(balance1, 1500e18);
        assertEq(tokensCount1, 2, "tokensCount should remain 2 after push");
    }

    function testFuzzShipAmountDoesNotOverwriteTokenCount(uint248 amount1, uint248 amount2) public {
        // Bound amounts to what maker has available (10000e18 each token)
        amount1 = uint248(bound(amount1, 0, 10000e18));
        amount2 = uint248(bound(amount2, 0, 10000e18));

        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_fuzz",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(amount1), uint256(amount2)])
        );

        bytes32 strategyHash = keccak256("strategy_fuzz");

        // Verify tokensCount is always 2 regardless of amounts
        (, uint8 tokensCount1) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (, uint8 tokensCount2) = aqua.rawBalances(maker, app, strategyHash, address(token2));

        assertEq(tokensCount1, 2, "tokensCount must be 2 for any amount");
        assertEq(tokensCount2, 2, "tokensCount must be 2 for any amount");
    }

    function testShipWithZeroAmounts() public {
        // Ship with zero amounts - should succeed (no require check for zero)
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy_zero",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(0), uint256(0)])
        );

        bytes32 strategyHash = keccak256("strategy_zero");

        // Verify balances are zero but strategy is active
        (uint256 balance1, uint8 tokensCount1) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (uint256 balance2, uint8 tokensCount2) = aqua.rawBalances(maker, app, strategyHash, address(token2));

        assertEq(balance1, 0);
        assertEq(balance2, 0);
        assertEq(tokensCount1, 2); // Strategy is active with 2 tokens
        assertEq(tokensCount2, 2);

        // Push should still work on this strategy
        vm.prank(pusher);
        aqua.push(maker, app, strategyHash, address(token1), 50e18);

        (balance1,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        assertEq(balance1, 50e18);
    }

    // ========== DOCK TESTS ==========

    function testDockRequiresAllTokensFromShip() public {
        // Ship with 2 tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy2",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Try to dock with only 1 token
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.DockingShouldCloseAllTokens.selector, app, keccak256("strategy2")));
        aqua.dock(
            app,
            keccak256("strategy2"),
            dynamic([address(token1)])
        );
    }

    function testDockRequiresExactTokensFromShip() public {
        // Ship with specific tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy3",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Try to dock with different token
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.DockingShouldCloseAllTokens.selector, app, keccak256("strategy3")));
        aqua.dock(
            app,
            keccak256("strategy3"),
            dynamic([address(token1), address(token3)])
        );
    }

    function testDockRequiresCorrectTokenCount() public {
        // Ship with 2 tokens
        vm.prank(maker);
        aqua.ship(
            app,
            "strategy4",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Try to dock with 3 tokens
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.DockingShouldCloseAllTokens.selector, app, keccak256("strategy4")));
        aqua.dock(
            app,
            keccak256("strategy4"),
            dynamic([address(token1), address(token2), address(token3)])
        );
    }

    function testDockNonExistentStrategyReverts() public {
        // Try to dock a strategy that was never shipped
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.DockingShouldCloseAllTokens.selector, app, keccak256("nonexistent")));
        aqua.dock(
            app,
            keccak256("nonexistent"),
            dynamic([address(token1)])
        );
    }

    function testDockAlreadyDockedStrategyReverts() public {
        // Ship a strategy
        vm.prank(maker);
        aqua.ship(
            app,
            "dock_twice",
            dynamic([address(token1)]),
            dynamic([uint256(100e18)])
        );

        // Dock the strategy
        vm.prank(maker);
        aqua.dock(
            app,
            keccak256("dock_twice"),
            dynamic([address(token1)])
        );

        // Try to dock again - should fail because tokensCount is now _DOCKED (255)
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.DockingShouldCloseAllTokens.selector, app, keccak256("dock_twice")));
        aqua.dock(
            app,
            keccak256("dock_twice"),
            dynamic([address(token1)])
        );
    }

    // ========== SHIP + DOCK COMBINED TESTS ==========

    function testShipDockShipSameStrategyReverts() public {
        bytes32 strategyHash = keccak256("reship");

        // 1. Ship with specific tokens and amounts
        vm.prank(maker);
        aqua.ship(
            app,
            "reship",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );

        // Verify initial balances
        (uint256 balance1,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (uint256 balance2,) = aqua.rawBalances(maker, app, strategyHash, address(token2));
        assertEq(balance1, 100e18);
        assertEq(balance2, 200e18);

        // 2. Dock the strategy
        vm.prank(maker);
        aqua.dock(
            app,
            strategyHash,
            dynamic([address(token1), address(token2)])
        );

        // Verify balances are zero after dock
        (balance1,) = aqua.rawBalances(maker, app, strategyHash, address(token1));
        (balance2,) = aqua.rawBalances(maker, app, strategyHash, address(token2));
        assertEq(balance1, 0);
        assertEq(balance2, 0);

        // 3. Attempt to ship again with the same strategy - should revert
        // Strategies are immutable: once docked, cannot be re-shipped with the same salt
        vm.prank(maker);
        vm.expectRevert(abi.encodeWithSelector(IAqua.StrategiesMustBeImmutable.selector, app, strategyHash));
        aqua.ship(
            app,
            "reship",
            dynamic([address(token1), address(token2)]),
            dynamic([uint256(100e18), uint256(200e18)])
        );
    }
}

